// src/components/Quiz/Header.jsx
import React from 'react';
import { Link } from 'react-router-dom';
import { useAuthContext } from '../../hooks/useAuthContext';
import { useAdmin } from '../../hooks/UseAdmin';

const Header = () => {
  const { user } = useAuthContext();
  const { isAdmin } = useAdmin();

  return (
    <header className="admin-header">
      <nav className="admin-nav">
        <div className="nav-brand">
          <Link to="/">Plateforme E-Learning</Link>
        </div>
        
        <div className="nav-links">
          <Link to="/" className="nav-link">
            Accueil
          </Link>
          <Link to="/catalog" className="nav-link">
            Catalogue
          </Link>
          
          {user && (
            <Link to="/my-courses" className="nav-link">
              Mes Cours
            </Link>
          )}
          
          {isAdmin && (
            <>
              <Link to="/admin/dashboard" className="nav-link">
                Tableau de bord
              </Link>
              <Link to="/admin/quiz" className="nav-link">
                Gestion des Quiz
              </Link>
            </>
          )}
          
          {user ? (
            <div className="user-menu">
              <span className="user-name">Bonjour, {user.displayName}</span>
              <button className="btn-logout">Déconnexion</button>
            </div>
          ) : (
            <div className="auth-links">
              <Link to="/login" className="nav-link">
                Connexion
              </Link>
              <Link to="/register" className="btn btn-primary">
                Inscription
              </Link>
            </div>
          )}
        </div>
      </nav>
    </header>
  );
};

export default Header;
